    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        BST tree = new BST();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            String op = st.nextToken();
            if (op.equals("inorder")) {
                List<Long> keys = tree.inorder();
                if (keys.isEmpty()) sb.append("EMPTY");
                for (int j = 0; j < keys.size(); j++) sb.append(keys.get(j)).append(j + 1 < keys.size() ? " " : "");
                sb.append('\n');
                continue;
            }
            long x = Long.parseLong(st.nextToken());
            if (op.equals("insert")) tree.insert(x);
            else if (op.equals("delete")) tree.delete(x);
            else if (op.equals("find")) sb.append(tree.find(x) ? 1 : 0).append('\n');
            else if (op.equals("succ")) sb.append(tree.succ(x)).append('\n');
            else sb.append(tree.depth(x)).append('\n');
        }
        System.out.print(sb);
    }
}
